 "content": "def transform(grid):
    """Mark original nonzero cells with 0; recolor the zero background by source color."""
    source_colors = {cell for row in grid for cell in row if cell != 0}
    if len(source_colors) != 1:
        raise ValueError("Expected a single nonzero source color")
    color = next(iter(source_colors))
    background_color = {3: 1, 8: 2}[color]
    return [[0 if cell != 0 else background_color for cell in row] for row in grid]
